code_sketch:
let readings = AsyncStream<Reading>(bufferingPolicy: .bufferingNewest(64)) { cont in
    sensor.onSample { cont.yield($0) }        // newest wins; older buffered samples dropped
    return { sensor.stop() }
}
for await r in readings { store(r) }          // the consumer drains at its own rate

